import{_ as a,o as d,c as e,a5 as i}from"./chunks/framework.bIR-4glx.js";const k=JSON.parse('{"title":"实践篇：先把第一周过完","description":"在宏大计划之前，用一个真实问题、一份起点样本、七天最小行动和一次周末复测，让生活而不是热情决定下一步。","frontmatter":{"title":"实践篇：先把第一周过完","description":"在宏大计划之前，用一个真实问题、一份起点样本、七天最小行动和一次周末复测，让生活而不是热情决定下一步。","updated":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-4/week-1.md","filePath":"threads/part-4/week-1.md","lastUpdated":1788220800000}'),s={name:"threads/part-4/week-1.md"};function r(l,t,n,p,h,o){return d(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="实践篇-先把第一周过完" tabindex="-1">实践篇：先把第一周过完 <a class="header-anchor" href="#实践篇-先把第一周过完" aria-label="Permalink to &quot;实践篇：先把第一周过完&quot;">​</a></h1><p>人在重新开始时，很容易对第一天寄予过高的期望。</p><p>我们打开一本新书，建好文件夹，买来设备，排出未来三个月的日程，仿佛只要开头足够郑重，后面的自己就会自动出现。可真正让计划失去重量的，往往不是第一天没有热情，而是第三天临时加班，第五天没睡好，第六天有人需要照顾，第七天已经不愿再看那张写得太满的表。</p><p>所以，第一周不负责证明你已经改变。它只负责回答一个更诚实的问题：<strong>这件事放进我的真实生活之后，还能不能继续？</strong></p><p>这一周，你不需要表演自律，也不需要把低谷写成逆袭。你只需要留下一个未经修饰的起点，完成几次足够小的动作，再看见什么条件帮助了你，什么条件让你失去能力。生活给出的答案，通常比第一天的决心更有用。</p><h2 id="本章速览" tabindex="-1">本章速览 <a class="header-anchor" href="#本章速览" aria-label="Permalink to &quot;本章速览&quot;">​</a></h2><ul><li>只带一个真实问题进入第一周，不同时改造整个人生；</li><li>在使用 AI、课程或模板之前，保存一份未经辅助的起点样本；</li><li>用七天完成输入、输出、反馈、延迟复测和一次迁移；</li><li>为完整日、压缩日和恢复日准备不同重量的动作；</li><li>周末只保留一个有效条件、删除一个无效要求，并决定是否进入下一周。</li></ul><h2 id="_1-第一周不是缩小版的九十天" tabindex="-1">1. 第一周不是缩小版的九十天 <a class="header-anchor" href="#_1-第一周不是缩小版的九十天" aria-label="Permalink to &quot;1. 第一周不是缩小版的九十天&quot;">​</a></h2><p>很多七天计划，只是把九十天的野心压缩进更小的格子：每天学习、每天运动、每天阅读、每天早起，还要记录情绪和反思。看起来完整，实际把“观察生活”变成了“同时参加五场考试”。</p><p>第一周真正需要留下的只有三样东西：</p><ol><li><strong>一份起点样本</strong>：现在独立完成时，结果是什么样；</li><li><strong>几次真实尝试</strong>：在不同容量和环境里，能否再次开始；</li><li><strong>一次周末决定</strong>：下一周保留什么、停止什么、改变什么。</li></ol><p>这一周不是用来估计你有多大潜力，而是用来发现系统条件。你可能发现早晨并不适合深度学习，通勤时却愿意听材料；也可能发现自己不是缺时间，而是每次打开任务都不知道第一步；还可能发现疲惫已经持续影响生活，需要先处理健康和责任，而不是继续增加训练。</p><p>能更早看见这些事实，不是失败。它避免你用更长的计划掩盖一个本来可以更早调整的问题。</p><h2 id="_2-只带一个问题进入这一周" tabindex="-1">2. 只带一个问题进入这一周 <a class="header-anchor" href="#_2-只带一个问题进入这一周" aria-label="Permalink to &quot;2. 只带一个问题进入这一周&quot;">​</a></h2><p>一个好问题必须同时满足三项条件：与真实生活有关，七天内可以观察，而且答案可能改变下一步。</p><table tabindex="0"><thead><tr><th>场景</th><th>过于宽泛的目标</th><th>第一周可以回答的问题</th></tr></thead><tbody><tr><td>英语</td><td>提高口语</td><td>我能否用英语说明一次真实困难，并回应一个追问？</td></tr><tr><td>工作</td><td>提高编程能力</td><td>我能否独立修复一个真实问题，写出测试和变更说明？</td></tr><tr><td>写作</td><td>开始持续输出</td><td>我能否完成一篇让陌生读者复述主旨的短文？</td></tr><tr><td>生活</td><td>变得自律</td><td>我能否在三种容量下，都给明天留下一个明确入口？</td></tr><tr><td>关系</td><td>学会沟通</td><td>我能否说明一个边界，同时说清楚何时回来回应？</td></tr></tbody></table><p>不要选择一个答案必定是“继续努力”的问题。真正的问题应当允许三种结果：继续、缩小，或停止。</p><p>可以先写下：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">这一周只回答的问题：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">它发生在哪个真实场景：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">周末用什么证据回答：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">什么结果会让我缩小或停止：</span></span></code></pre></div><p>如果问题涉及持续失眠、疼痛、低落、失控或危险念头，第一周的目标应先改成记录事实、保证安全和寻求当地合格专业支持。本章不能替代医疗或心理照护。</p><h2 id="_3-第一天-保存未经修饰的起点" tabindex="-1">3. 第一天，保存未经修饰的起点 <a class="header-anchor" href="#_3-第一天-保存未经修饰的起点" aria-label="Permalink to &quot;3. 第一天，保存未经修饰的起点&quot;">​</a></h2><p>在请 AI 改写、观看教程或套用模板之前，先独立完成一次。时间控制在 10–25 分钟，不查找完美答案，也不为了好看反复重录。</p><p>起点可以是一段 90 秒录音、一页短文、一次代码修改、一封真实邮件、一段阅读重构，或一次边界沟通的草稿。它不需要公开，但必须能够在第六天或第七天再次比较。</p><p>为样本附上五行说明：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">日期与场景：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">任务和限制：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我独立完成的版本：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">最明显的三个困难：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">一周后使用什么新条件复测：</span></span></code></pre></div><p>起点难看是正常的。它的任务不是维护自尊，而是防止未来的你只凭感觉回忆“以前好像更差”。没有起点，进步容易被兴奋夸大，退步也容易被当天的情绪夸大。</p><p>保存之后，再决定是否使用 AI、同伴或课程。工具可以帮助你分析错误、生成平行任务和提供反馈，但不能替你补写这份基线。</p><h2 id="_4-七天不求满格-只求能够回来" tabindex="-1">4. 七天不求满格，只求能够回来 <a class="header-anchor" href="#_4-七天不求满格-只求能够回来" aria-label="Permalink to &quot;4. 七天不求满格，只求能够回来&quot;">​</a></h2><p>下面不是必须逐项打卡的课程表，而是一条最小证据链。某一天被打断，可以合并动作；如果容量下降，缩小输出，不熬夜补偿。</p><table tabindex="0"><thead><tr><th>天数</th><th>只做一件事</th><th>留下的证据</th></tr></thead><tbody><tr><td>第 1 天</td><td>完成未经辅助的起点样本</td><td>首版和三个困难</td></tr><tr><td>第 2 天</td><td>找一份高质量输入，只处理一个困难</td><td>来源、主旨和一个可复用结构</td></tr><tr><td>第 3 天</td><td>在关闭材料后完成第二版</td><td>输出和与首版的差异</td></tr><tr><td>第 4 天</td><td>获得一次具体反馈</td><td>原话、可验证问题和不采纳的建议</td></tr><tr><td>第 5 天</td><td>只改一个变量，完成第三版</td><td>修改前后版本</td></tr><tr><td>第 6 天</td><td>不看笔记，做一次延迟复测</td><td>保留与遗忘的部分</td></tr><tr><td>第 7 天</td><td>更换主题、听众或限制，测试迁移</td><td>新条件下的结果和下一周决定</td></tr></tbody></table><p>如果七天里只完成四天，不要伪造连续性。把缺席写成事实：发生了什么，改变了哪个条件，回来的成本有多大。比“连续七天”更重要的证据，是中断之后你是否仍然知道从哪里继续。</p><h2 id="_5-一个真实例子-用英语谈疲惫" tabindex="-1">5. 一个真实例子：用英语谈疲惫 <a class="header-anchor" href="#_5-一个真实例子-用英语谈疲惫" aria-label="Permalink to &quot;5. 一个真实例子：用英语谈疲惫&quot;">​</a></h2><p>假设这一周的问题是：<strong>我能否不用逐句翻译，用英语说明自己为什么疲惫、需要什么支持，并回应一个追问？</strong></p><p>疲惫可能来自睡眠、疾病、压力、照护责任、工作安排或许多其他原因。这里练习的是表达，不是诊断。持续影响生活的睡眠或身体问题，应交给合格专业人士评估。</p><p>先保留五个可以迁移到日常沟通的结构：</p><table tabindex="0"><thead><tr><th>英文结构</th><th>它承担的作用</th><th>你的句子</th></tr></thead><tbody><tr><td><code>I have been feeling ...</code></td><td>描述近期状态，不把感受写成永久身份</td><td></td></tr><tr><td><code>What makes it harder is ...</code></td><td>指出一个可观察条件</td><td></td></tr><tr><td><code>I am not sure whether ...</code></td><td>保留不确定性，不假装诊断</td><td></td></tr><tr><td><code>What I need this week is ...</code></td><td>提出具体、有限的支持</td><td></td></tr><tr><td><code>If this continues, I will ...</code></td><td>说明下一项求助或检查动作</td><td></td></tr></tbody></table><p>第一天录一段 90 秒音频。第三天，在看过一份可靠材料或获得语言反馈后重录；第六天不看稿再说一次；第七天把听众从“朋友”换成“同事”或“专业人士”，观察用词和边界是否改变。</p><p>评分时不要只数语法错误。检查对方能否回答三件事：发生了什么，你不能确认什么，你希望下一步怎样做。能让真实沟通继续，比模仿某一种口音更接近可用的流利。</p><h2 id="_6-低谷里的作品-不负责拯救人生" tabindex="-1">6. 低谷里的作品，不负责拯救人生 <a class="header-anchor" href="#_6-低谷里的作品-不负责拯救人生" aria-label="Permalink to &quot;6. 低谷里的作品，不负责拯救人生&quot;">​</a></h2><p>在我生活失序的一段时间里，编程给过我一个很小的行动入口。以前公司的产品需要一款高性能富文本编辑器，我没有找到满足需求的开源项目，于是开始做 Editable，并把它发布到 GitHub。</p><p>这个项目包含编辑器内核、插件系统、复杂表格数据结构和渲染引擎等问题。我花了很长时间逐步完成，也向 Slate.js 提交过相关工作。你可以查看 <a href="https://github.com/editablejs/editable" target="_blank" rel="noreferrer">Editable 项目</a>。</p><p>我不愿再把这段经历写成“编程治好了我”或“只要找到热爱就能走出低谷”。项目没有解决所有问题，也不能替代照护。它当时真正提供的，是一个边界清楚的小时：问题可以被拆分，代码可以被测试，今天完成的一小段不会因为情绪改变而消失。</p><p>第一周选择作品时，也不必寻找能证明人生价值的大项目。选择一个七天内可以关门的东西：</p><ul><li>修复一个能够复现的问题，并补上测试；</li><li>写完一页有明确读者的说明；</li><li>录制一段可以获得追问的表达；</li><li>改善一个真实使用者每天都会经过的步骤；</li><li>提交一个范围清楚、可以被拒绝的贡献。</li></ul><p>作品的作用不是拯救你，而是让判断进入现实。它会告诉你：问题是否真实，能力缺口在哪里，别人是否能使用，以及下一次是否值得继续。</p><h2 id="_7-给容量准备三个档位" tabindex="-1">7. 给容量准备三个档位 <a class="header-anchor" href="#_7-给容量准备三个档位" aria-label="Permalink to &quot;7. 给容量准备三个档位&quot;">​</a></h2><p>第一周最容易失败，不是因为动作太少，而是计划只承认一种理想状态。提前写好三个档位：</p><table tabindex="0"><thead><tr><th>档位</th><th>可用容量</th><th>当天动作</th></tr></thead><tbody><tr><td>完整日</td><td>30–45 分钟完整注意力</td><td>输入、输出和一句记录</td></tr><tr><td>压缩日</td><td>10–20 分钟或被多次打断</td><td>只完成最小输出，标记下一个错误</td></tr><tr><td>恢复日</td><td>生病、失眠、悲伤或责任激增</td><td>保护安全和基本照料，只准备下次入口</td></tr></tbody></table><p>恢复日不要求生成作品。把材料放到桌面、写下明天第一步、向相关的人说明延迟，都可以是回归动作。如果连续几天只能运行恢复档，先回到<a href="./../part-2/recovery">恢复篇：先把自己接住</a>，检查身体、安全和支持网络。</p><p>如果正在支持未成年学习者，下一章先进入<a href="./family-learning">家庭学习篇</a>，把孩子、家长、学校与 AI 的角色边界说清楚；其他读者可以继续到<a href="./daily-system">生活系统篇</a>，处理精力预算、环境设计、关系边界和中断回归。第一周只需要证明一件事：你愿意根据容量改变任务，而不是根据任务惩罚自己。</p><h2 id="_8-周末只回答四个问题" tabindex="-1">8. 周末只回答四个问题 <a class="header-anchor" href="#_8-周末只回答四个问题" aria-label="Permalink to &quot;8. 周末只回答四个问题&quot;">​</a></h2><p>第七天不要先问“我是否足够努力”。把首版、反馈、延迟复测和迁移结果并排放进<a href="./../../templates/evidence-chain">证据链模板</a>，再回答四个问题：</p><ol><li><strong>完成</strong>：我是否在真实限制下完成了目标动作？</li><li><strong>质量</strong>：输出在哪个可观察维度发生了变化？</li><li><strong>保持</strong>：离开材料之后，还剩下什么？</li><li><strong>迁移</strong>：更换主题、听众或环境后，能力是否仍然可用？</li></ol><p>然后写两句决定：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一周保留的一个条件：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一周删除或降低的一个要求：</span></span></code></pre></div><p>不要因为一周顺利，就立刻把任务翻倍；也不要因为一周混乱，就宣布自己不适合。使用<a href="./../../templates/weekly-review">每周复盘模板</a>把事实、解释和下一次实验分开。第一周样本太少，足以调整方向，不足以定义一个人。</p><h2 id="结语-第一周不证明你是谁" tabindex="-1">结语：第一周不证明你是谁 <a class="header-anchor" href="#结语-第一周不证明你是谁" aria-label="Permalink to &quot;结语：第一周不证明你是谁&quot;">​</a></h2><p>第一周结束时，你可能只有三段不流利的录音、一个仍未完全修好的问题、一页被改得很乱的文字，或几天断断续续的记录。它们看起来不像改变人生，却比一份从未进入生活的宏大计划更接近未来。</p><p>真正的开始，不是第一天有多激动，而是生活打断之后，你仍能找到文件、看见下一步、承认今天的容量，然后完成一个不需要表演的动作。</p><p>先把第一周过完。让事实替热情筛选方向，让作品替愿望留下痕迹，让一次周末决定为下一周减轻重量。</p><p>你不需要在七天里证明自己是谁。你只需要为第八天，留下一条愿意再次走进去的路。</p>`,61)])])}const b=a(s,[["render",r]]);export{k as __pageData,b as default};
